 IF EXISTS(SELECT 1 FROM grammar.content_releases WHERE version='core-2026-09-v4' AND content_hash<>'87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d') THEN RAISE EXCEPTION 'Published release is immutable'; END IF;
 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v4' AND slug='question-forms' AND (catalog_hash<>'87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d' OR payload_md5<>'3fa0713af71c1b6e4f75f0f5d8890fc5')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
