INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','question-forms','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"question-forms","title":"Questions, question words and short answers","level":"A1","order":11,"summary":"Build direct questions and distinguish a question about the subject from one about the object.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Use the existing auxiliary","Add do when needed","Subject questions","Short answers"],"rules":[{"title":"Use the existing auxiliary","explanation":"If a statement already has be, a modal or an auxiliary have, put the first auxiliary before the subject. The rest of the verb phrase remains after the subject. A question word, if needed, normally comes first.","pattern":"**Are** they ready? / Where **have** they gone?","commonMistakes":["Do not add do to a question already built with auxiliary be: Are they waiting?, not Do they are waiting?"],"examples":["Present simple: “**Does** the assistant prepare the visitor guide every day?”","Present simple: “**Does** the assistant restore the old portrait every day?”"],"skill":"form"},{"title":"Add do when needed","explanation":"For an ordinary present-simple action verb, add **do / does**. For past simple, add **did**. These auxiliaries carry tense and agreement, so the main verb uses its base form.","pattern":"Where **does** she **work**? / What **did** they **buy**?","commonMistakes":["Does she works? marks agreement twice. Keep the -s on does, not on the main verb."],"examples":["Complete the past-simple question: “Why did the assistant **prepare** the visitor guide?”","Complete the past-simple question: “Why did the assistant **restore** the old portrait?”"],"skill":"meaning"},{"title":"Subject questions","explanation":"When who or what is itself the subject, a neutral affirmative question usually has normal subject–verb order without do. Compare Who called you? with Who did you call? The person sought has a different role.","pattern":"**Who called**? / **Who did you call**?","commonMistakes":["Emphatic subject questions can use do, as in Who did call? These exercises practise the neutral pattern."],"examples":["Ask who performs the action, in the neutral present simple: “Who **prepares** the visitor guide each morning?”","Ask who performs the action, in the neutral present simple: “Who **restores** the old portrait each morning?”"],"skill":"contrast"},{"title":"Short answers","explanation":"Use a pronoun and the same auxiliary family as the question: Do they work? Yes, they do. Can she swim? No, she can’t. In a positive short answer, keep the auxiliary full rather than ending with a contraction.","pattern":"Yes, she **does**. / No, they **did not**.","commonMistakes":["Yes, she’s is not a normal complete positive short answer to Is she ready? Use Yes, she is."],"examples":["“Did they prepare the visitor guide yesterday?” Complete the positive short answer: “Yes, they **did**.”","“Did they restore the old portrait yesterday?” Complete the positive short answer: “Yes, they **did**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Build direct questions and distinguish a question about the subject from one about the object.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Use the existing auxiliary","explanation":"If a statement already has be, a modal or an auxiliary have, put the first auxiliary before the subject. The rest of the verb phrase remains after the subject. A question word, if needed, normally comes first.","pattern":"**Are** they ready? / Where **have** they gone?","commonMistakes":["Do not add do to a question already built with auxiliary be: Are they waiting?, not Do they are waiting?"],"examples":["Present simple: “**Does** the assistant prepare the visitor guide every day?”","Present simple: “**Does** the assistant restore the old portrait every day?”"],"skill":"form","id":"question-forms-foundation-1","domain":"sentence-types","referenceIds":["bc-question-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Add do when needed","explanation":"For an ordinary present-simple action verb, add **do / does**. For past simple, add **did**. These auxiliaries carry tense and agreement, so the main verb uses its base form.","pattern":"Where **does** she **work**? / What **did** they **buy**?","commonMistakes":["Does she works? marks agreement twice. Keep the -s on does, not on the main verb."],"examples":["Complete the past-simple question: “Why did the assistant **prepare** the visitor guide?”","Complete the past-simple question: “Why did the assistant **restore** the old portrait?”"],"skill":"meaning","id":"question-forms-foundation-2","domain":"sentence-types","referenceIds":["bc-question-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Subject questions","explanation":"When who or what is itself the subject, a neutral affirmative question usually has normal subject–verb order without do. Compare Who called you? with Who did you call? The person sought has a different role.","pattern":"**Who called**? / **Who did you call**?","commonMistakes":["Emphatic subject questions can use do, as in Who did call? These exercises practise the neutral pattern."],"examples":["Ask who performs the action, in the neutral present simple: “Who **prepares** the visitor guide each morning?”","Ask who performs the action, in the neutral present simple: “Who **restores** the old portrait each morning?”"],"skill":"contrast","id":"question-forms-foundation-3","domain":"sentence-types","referenceIds":["bc-question-forms"],"readingVersion":"core-2026-09-v3"},{"title":"Short answers","explanation":"Use a pronoun and the same auxiliary family as the question: Do they work? Yes, they do. Can she swim? No, she can’t. In a positive short answer, keep the auxiliary full rather than ending with a contraction.","pattern":"Yes, she **does**. / No, they **did not**.","commonMistakes":["Yes, she’s is not a normal complete positive short answer to Is she ready? Use Yes, she is."],"examples":["“Did they prepare the visitor guide yesterday?” Complete the positive short answer: “Yes, they **did**.”","“Did they restore the old portrait yesterday?” Complete the positive short answer: “Yes, they **did**.”"],"skill":"application","id":"question-forms-foundation-4","domain":"sentence-types","referenceIds":["bc-question-forms"],"readingVersion":"core-2026-09-v3"},{"domain":"sentence-types","id":"question-word-range","title":"What, which, whose, who and how","explanation":"Who asks about a person; whose asks about possession. What often asks for open information, while which usually selects from an understood set. How forms phrases about manner, degree, age, frequency and quantity. A question phrase may contain a noun or modifier and move as a unit.","pattern":"**Which train** / **How often** / **Whose coat**","examples":["**Which of these routes** is quickest?","**How long** have you lived here?"],"commonMistakes":["What and which overlap when the context supplies alternatives. Do not choose between them using a rigid noun-only rule."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"sentence-types","id":"negative-and-alternative-questions","title":"Negative questions, alternatives and replies","explanation":"Negative questions can express surprise, confirmation or an invitation. Alternative questions ask the listener to choose, rather than simply answer yes or no. In standard English, yes normally confirms a positive proposition and no confirms a negative one; repeating the verb removes uncertainty in replies to negative questions.","pattern":"Didn’t you go? — **Yes, I did. / No, I didn’t.**","examples":["Would you prefer **tea or coffee**?","**Isn’t she coming?** — No, she isn’t."],"commonMistakes":["The tone and context of a negative question matter: Wouldn’t you like a seat? can be an offer, not an accusation."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"sentence-types","id":"echo-rhetorical-questions","title":"Echo, checking and rhetorical questions","explanation":"An echo question repeats or queries information just heard and may keep statement word order. A checking question asks for confirmation. A rhetorical question has question form but often makes a point instead of seeking new information. These uses depend strongly on conversation and intonation.","pattern":"You paid **how much**?","examples":["You’re leaving **today**?","Who could refuse an offer like that?"],"commonMistakes":["Statement word order in an echo question does not license the same order for every neutral information question: Where do you live? is the ordinary direct form."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Are** they ready? / Where **have** they gone?","Where **does** she **work**? / What **did** they **buy**?","**Who called**? / **Who did you call**?","Yes, she **does**. / No, they **did not**."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["present-simple"],"readingReferenceIds":["bc-question-forms","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='question-forms'
